        "path": "expressions/values.ds",
        "kind": "source",
        "source": "/**\n * Almost all statements are expressions that produce values: the last expression\n * of a block (no trailing semicolon) becomes the block's value, and functions\n * return their final expression implicitly.\n */\n\n// conditionals are values\nconst mode: string = if (3 > 2) {\n    \"forward\"\n} else {\n    \"reverse\"\n};\n\n// functions return their last expression\nfunction add(a: int, b: int): int {\n    a + b\n}\n\n// `do { ... }` turns a block into an expression where braces would be ambiguous\nconst total = do {\n    const base = add(40, 1);\n    base + 1\n};\n\n// if-let matches a refutable pattern, bindings flow into the positive branch\nconst maybe: int | null = 7;\nconst value = if (let found! = maybe) {\n    found\n} else {\n    0\n};\n\nconsole.log(`mode=${mode} total=${total} value=${value}`);\n",
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\"> * Almost all statements are expressions that produce values: the last expression</span>\n<span data-k=\"comment\"> * of a block (no trailing semicolon) becomes the block's value, and functions</span>\n<span data-k=\"comment\"> * return their final expression implicitly.</span>\n<span data-k=\"comment\"> */</span>\n\n<span data-k=\"comment\">// conditionals are values</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">mode</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"literal\">3</span> <span data-k=\"punct\">&gt;</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"string\">&quot;forward&quot;</span>\n<span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"string\">&quot;reverse&quot;</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// functions return their last expression</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">add</span><span data-k=\"punct\">(</span><span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span><span data-k=\"punct\">,</span> <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">a</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">b</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// `do { ... }` turns a block into an expression where braces would be ambiguous</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">total</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">do</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">base</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">add</span><span data-k=\"punct\">(</span><span data-k=\"literal\">40</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">base</span> <span data-k=\"punct\">+</span> <span data-k=\"literal\">1</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// if-let matches a refutable pattern, bindings flow into the positive branch</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">maybe</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">null</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">7</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">value</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">let</span> <span data-k=\"name\">found</span><span data-k=\"punct\">!</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">maybe</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">found</span>\n<span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"literal\">0</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`mode=${mode} total=${total} value=${value}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n"
