        "path": "expressions/closures.ds",
        "kind": "source",
        "source": "/**\n * Closures work like TypeScript's: they capture the surrounding lexical\n * environment, and captures preserve variable identity by default - every\n * closure over a variable observes the same storage.\n * Arrow types are sugar for `Function<Parameters, Return>`.\n */\n\nlet count = 0;\n\n// both closures capture the same `count` storage\nconst next = () => {\n    count += 1;\n    return count;\n};\nconst read = () => count;\n\nnext satisfies () => number;\nnext satisfies Function<(), number>;\n\nnext();\nnext();\n\nconsole.log(`count=${read()} after two calls`);\n\n// closures close over parameters too\nfunction counter(start: int): () => int {\n    let current = start;\n    return () => {\n        current += 1;\n        return current;\n    };\n}\n\nconst tick = counter(100);\ntick();\n\nconsole.log(`tick=${tick()}`);\n",
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\"> * Closures work like TypeScript's: they capture the surrounding lexical</span>\n<span data-k=\"comment\"> * environment, and captures preserve variable identity by default - every</span>\n<span data-k=\"comment\"> * closure over a variable observes the same storage.</span>\n<span data-k=\"comment\"> * Arrow types are sugar for `Function&lt;Parameters, Return&gt;`.</span>\n<span data-k=\"comment\"> */</span>\n\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">count</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// both closures capture the same `count` storage</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">next</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">count</span> <span data-k=\"punct\">+=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">;</span>\n    <span data-k=\"keyword\">return</span> <span data-k=\"name\">count</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">read</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">count</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">next</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">next</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Function</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">,</span> <span data-k=\"type\">number</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">next</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">next</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`count=${read()} after two calls`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// closures close over parameters too</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">counter</span><span data-k=\"punct\">(</span><span data-k=\"name\">start</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"type\">int</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">let</span> <span data-k=\"name\">current</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">start</span><span data-k=\"punct\">;</span>\n    <span data-k=\"keyword\">return</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">current</span> <span data-k=\"punct\">+=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">;</span>\n        <span data-k=\"keyword\">return</span> <span data-k=\"name\">current</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">tick</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">counter</span><span data-k=\"punct\">(</span><span data-k=\"literal\">100</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">tick</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`tick=${tick()}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n"
