        "path": "expressions/patterns.ds",
        "kind": "source",
        "source": "/**\n * TypeScript's destructuring, extended into a full pattern suite: nominal\n * objects, newtypes, tuples, slices, defaults, and the must pattern, usable in\n * `let`, parameters, `match`, `if (let ...)`, and `let ... else`.\n */\n\nstruct Point {\n    x: int;\n    y: int;\n}\n\nnewtype UserId = uint64;\n\n// nominal object patterns destructure stored fields\nconst Point { x, y } = Point { x: 3, y: 4 };\n\n// newtype patterns unwrap the backing value\nconst UserId(id) = UserId(7);\n\n// defaults bind fallbacks for missing destructured values\nconst { name = \"guest\" }: { name?: string } = {};\n\n// `let ... else` takes the refutable case out of line\nfunction describe(maybe: int | null): string {\n    let value! = maybe else {\n        return \"nothing\";\n    };\n\n    `value ${value}`\n}\n\nconsole.log(`point=(${x}, ${y}) id=${id} name=${name}`);\nconsole.log(describe(42));\nconsole.log(describe(null));\n",
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\"> * TypeScript's destructuring, extended into a full pattern suite: nominal</span>\n<span data-k=\"comment\"> * objects, newtypes, tuples, slices, defaults, and the must pattern, usable in</span>\n<span data-k=\"comment\"> * `let`, parameters, `match`, `if (let ...)`, and `let ... else`.</span>\n<span data-k=\"comment\"> */</span>\n\n<span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">newtype</span> <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// nominal object patterns destructure stored fields</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">4</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// newtype patterns unwrap the backing value</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">(</span><span data-k=\"literal\">7</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// defaults bind fallbacks for missing destructured values</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"punct\">{</span> name <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;guest&quot;</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">name</span><span data-k=\"punct\">?</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// `let ... else` takes the refutable case out of line</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">describe</span><span data-k=\"punct\">(</span><span data-k=\"name\">maybe</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">null</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">let</span> <span data-k=\"name\">value</span><span data-k=\"punct\">!</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">maybe</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"keyword\">return</span> <span data-k=\"string\">&quot;nothing&quot;</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"string\">`value ${value}`</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`point=(${x}, ${y}) id=${id} name=${name}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"name\">describe</span><span data-k=\"punct\">(</span><span data-k=\"literal\">42</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"name\">describe</span><span data-k=\"punct\">(</span><span data-k=\"literal\">null</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n"
