        "path": "expressions/operators.ds",
        "kind": "source",
        "source": "/**\n * Operators dispatch through nominal interfaces: `+` is `Add<T>`, `==` is\n * `PartialEqual<T>`, comparison is `Compare<T>` or `PartialCompare<T>`.\n * Any nominal type can implement them, and resolution is static.\n */\n\nstruct Vec2 {\n    x: float32;\n    y: float32;\n}\n\nextension of Vec2 implements Add {\n    type Output = Vec2;\n\n    add(other: Vec2): Vec2 {\n        Vec2 { x: this.x + other.x, y: this.y + other.y }\n    }\n}\n\nextension of Vec2 implements PartialEqual {\n    equal(other: Vec2): boolean {\n        this.x == other.x && this.y == other.y\n    }\n}\n\nconst a = Vec2 { x: 1.0, y: 2.0 };\nconst b = Vec2 { x: 3.0, y: 4.0 };\n\n// `+` and `==` now resolve through the implementations above\nconst sum = a + b;\nconst isSame = sum == Vec2 { x: 4.0, y: 6.0 };\n\nconsole.log(`sum=(${sum.x}, ${sum.y}) equal=${isSame}`);\n",
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\"> * Operators dispatch through nominal interfaces: `+` is `Add&lt;T&gt;`, `==` is</span>\n<span data-k=\"comment\"> * `PartialEqual&lt;T&gt;`, comparison is `Compare&lt;T&gt;` or `PartialCompare&lt;T&gt;`.</span>\n<span data-k=\"comment\"> * Any nominal type can implement them, and resolution is static.</span>\n<span data-k=\"comment\"> */</span>\n\n<span data-k=\"keyword\">struct</span> <span data-k=\"type\">Vec2</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">extension</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">Vec2</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">Add</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Output</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Vec2</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">add</span><span data-k=\"punct\">(</span><span data-k=\"name\">other</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Vec2</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Vec2</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"type\">Vec2</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">x</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">other</span><span data-k=\"punct\">.</span><span data-k=\"name\">x</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">y</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">other</span><span data-k=\"punct\">.</span><span data-k=\"name\">y</span> <span data-k=\"punct\">}</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">extension</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">Vec2</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">PartialEqual</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">equal</span><span data-k=\"punct\">(</span><span data-k=\"name\">other</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Vec2</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span> <span data-k=\"punct\">{</span>\n        this<span data-k=\"punct\">.</span><span data-k=\"name\">x</span> <span data-k=\"punct\">==</span> <span data-k=\"name\">other</span><span data-k=\"punct\">.</span><span data-k=\"name\">x</span> <span data-k=\"punct\">&amp;&amp;</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">y</span> <span data-k=\"punct\">==</span> <span data-k=\"name\">other</span><span data-k=\"punct\">.</span><span data-k=\"name\">y</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">a</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Vec2</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1.0</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2.0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">b</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Vec2</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">3.0</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">4.0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// `+` and `==` now resolve through the implementations above</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">sum</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">a</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">b</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">isSame</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">sum</span> <span data-k=\"punct\">==</span> <span data-k=\"type\">Vec2</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">4.0</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">6.0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`sum=(${sum.x}, ${sum.y}) equal=${isSame}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n"
