        "path": "types/structs.ds",
        "kind": "source",
        "source": "/**\n * Structs are nominal value types: data with a fixed shape and layout, without\n * reference identity, constructors, or inheritance.\n * They are created with the `T { .. }` constructor form, and spreads update\n * values while keeping the nominal type.\n */\n\nstruct Point {\n    x: float32;\n    y: float32;\n}\n\n// construction uses the struct form, `_` infers the type from context\nconst origin = Point { x: 0.0, y: 0.0 };\nconst unit: Point = _ { x: 1.0, y: 1.0 };\n\n// struct spreads update fields and stay nominal\nconst moved = Point { ...unit, y: 10.0 };\nmoved satisfies Point;\n\n// object spreads read struct fields but produce a structural object\nconst labeled = { ...moved, label: \"moved\" };\nlabeled satisfies { x: float32; y: float32; label: string };\n\n// and struct expressions can spread compatible object literals back in\nconst base = { x: 2.0, y: 3.0 };\nconst fromObject: Point = _ { ...base };\n\nconsole.log(`moved=(${moved.x}, ${moved.y}) ${labeled.label}`);\nconsole.log(`fromObject=(${fromObject.x}, ${fromObject.y})`);\n",
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\"> * Structs are nominal value types: data with a fixed shape and layout, without</span>\n<span data-k=\"comment\"> * reference identity, constructors, or inheritance.</span>\n<span data-k=\"comment\"> * They are created with the `T { .. }` constructor form, and spreads update</span>\n<span data-k=\"comment\"> * values while keeping the nominal type.</span>\n<span data-k=\"comment\"> */</span>\n\n<span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// construction uses the struct form, `_` infers the type from context</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">origin</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">0.0</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">0.0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">unit</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">_</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1.0</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1.0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// struct spreads update fields and stay nominal</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">moved</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">unit</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">10.0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">moved</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// object spreads read struct fields but produce a structural object</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">labeled</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">moved</span><span data-k=\"punct\">,</span> <span data-k=\"name\">label</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;moved&quot;</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">labeled</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span> <span data-k=\"name\">label</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// and struct expressions can spread compatible object literals back in</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">base</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2.0</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">3.0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">fromObject</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">_</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">base</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`moved=(${moved.x}, ${moved.y}) ${labeled.label}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`fromObject=(${fromObject.x}, ${fromObject.y})`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n"
