        "source": "/**\n * Beyond TypeScript's dynamic arrays, Destack has explicit slices, fixed arrays,\n * and tuples: `T[]` grows, `[T]` is a pointer plus length, `[T; N]` stores its\n * elements inline with the length in the type, and tuples are always `(A, B)`.\n */\n\n// fixed arrays know their length statically and live inline\nconst rgb: [uint8; 3] = [255, 128, 0];\n\n// fixed array patterns already know their length\nconst [r, g, b] = rgb;\n\n// slice patterns sniff structure with rest bindings\nfunction sniff(bytes: [uint8]): string {\n    match (bytes) {\n        [0x89, 0x50, 0x4e, 0x47, ...rest] => \"png\"\n        [0xff, 0xd8, ...rest] => \"jpeg\"\n        _ => \"unknown\"\n    }\n}\n\n// tuples are fixed heterogeneous products\nconst pair: (string, int32) = (\"answer\", 42);\nconst (label, value) = pair;\n\nconsole.log(`png header -> ${sniff([0x89, 0x50, 0x4e, 0x47, 0x0d])}`);\nconsole.log(`jpeg header -> ${sniff([0xff, 0xd8, 0xff])}`);\nconsole.log(`${label}=${value}, rgb=(${r}, ${g}, ${b})`);\n",
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\"> * Beyond TypeScript's dynamic arrays, Destack has explicit slices, fixed arrays,</span>\n<span data-k=\"comment\"> * and tuples: `T[]` grows, `[T]` is a pointer plus length, `[T; N]` stores its</span>\n<span data-k=\"comment\"> * elements inline with the length in the type, and tuples are always `(A, B)`.</span>\n<span data-k=\"comment\"> */</span>\n\n<span data-k=\"comment\">// fixed arrays know their length statically and live inline</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">rgb</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">255</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">128</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// fixed array patterns already know their length</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"punct\">[</span><span data-k=\"name\">r</span><span data-k=\"punct\">,</span> <span data-k=\"name\">g</span><span data-k=\"punct\">,</span> <span data-k=\"name\">b</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">rgb</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// slice patterns sniff structure with rest bindings</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">sniff</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">match</span> <span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"punct\">[</span><span data-k=\"literal\">0x89</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0x50</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0x4e</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0x47</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">rest</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;png&quot;</span>\n        <span data-k=\"punct\">[</span><span data-k=\"literal\">0xff</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0xd8</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">rest</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;jpeg&quot;</span>\n        <span data-k=\"name\">_</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;unknown&quot;</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// tuples are fixed heterogeneous products</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">pair</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">(</span><span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"string\">&quot;answer&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">42</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"punct\">(</span><span data-k=\"name\">label</span><span data-k=\"punct\">,</span> <span data-k=\"name\">value</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">pair</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`png header -&gt; ${sniff([0x89, 0x50, 0x4e, 0x47, 0x0d])}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`jpeg header -&gt; ${sniff([0xff, 0xd8, 0xff])}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`${label}=${value}, rgb=(${r}, ${g}, ${b})`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n"
