        "path": "types/extensions.ds",
        "kind": "source",
        "source": "/**\n * Extensions add instance and static members to any nominal type, including\n * types defined in other files or packages.\n * Members resolve statically - the `.asm` view shows direct calls with no\n * dynamic lookup.\n */\n\nclass Vector2 {\n    x: float32;\n    y: float32;\n\n    constructor(x: float32, y: float32) {\n        this.x = x;\n        this.y = y;\n    }\n}\n\n// extensions can live away from the type, here in the same file\nextension of Vector2 {\n    static ZERO = new Vector2(0.0, 0.0);\n\n    magnitude(): float32 {\n        return (this.x * this.x + this.y * this.y).sqrt();\n    }\n}\n\n// foreign types take extensions too; anonymous ones stay file-local\nextension of int32 {\n    isEven(): boolean {\n        return this % 2 == 0;\n    }\n}\n\nconst v = new Vector2(3.0, 4.0);\nconst count: int32 = 12;\n\nconsole.log(`magnitude=${v.magnitude()}`);\nconsole.log(`zero=(${Vector2.ZERO.x}, ${Vector2.ZERO.y})`);\nconsole.log(`${count} even? ${count.isEven()}`);\n",
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\"> * Extensions add instance and static members to any nominal type, including</span>\n<span data-k=\"comment\"> * types defined in other files or packages.</span>\n<span data-k=\"comment\"> * Members resolve statically - the `.asm` view shows direct calls with no</span>\n<span data-k=\"comment\"> * dynamic lookup.</span>\n<span data-k=\"comment\"> */</span>\n\n<span data-k=\"keyword\">class</span> <span data-k=\"type\">Vector2</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">constructor</span><span data-k=\"punct\">(</span><span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        this<span data-k=\"punct\">.</span><span data-k=\"name\">x</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">x</span><span data-k=\"punct\">;</span>\n        this<span data-k=\"punct\">.</span><span data-k=\"name\">y</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">y</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// extensions can live away from the type, here in the same file</span>\n<span data-k=\"keyword\">extension</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">Vector2</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">static</span> <span data-k=\"name\">ZERO</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Vector2</span><span data-k=\"punct\">(</span><span data-k=\"literal\">0.0</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0.0</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">magnitude</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"keyword\">return</span> <span data-k=\"punct\">(</span>this<span data-k=\"punct\">.</span><span data-k=\"name\">x</span> <span data-k=\"punct\">*</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">x</span> <span data-k=\"punct\">+</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">y</span> <span data-k=\"punct\">*</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">y</span><span data-k=\"punct\">)</span><span data-k=\"punct\">.</span><span data-k=\"name\">sqrt</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// foreign types take extensions too; anonymous ones stay file-local</span>\n<span data-k=\"keyword\">extension</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">isEven</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"keyword\">return</span> this <span data-k=\"punct\">%</span> <span data-k=\"literal\">2</span> <span data-k=\"punct\">==</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">v</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Vector2</span><span data-k=\"punct\">(</span><span data-k=\"literal\">3.0</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">4.0</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">count</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">12</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`magnitude=${v.magnitude()}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`zero=(${Vector2.ZERO.x}, ${Vector2.ZERO.y})`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">console</span><span data-k=\"punct\">.</span><span data-k=\"name\">log</span><span data-k=\"punct\">(</span><span data-k=\"string\">`${count} even? ${count.isEven()}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n"
